#!/usr/bin/env python3
# In a notebook, do not edit this file. It is generic - the template's, listed
# in .claude/notebook/manifest.txt - and the update skill replaces it; the
# notebook's pre-commit hook refuses a commit that changes it. To extend:
#   - a setting or an audit rule: .scripts/notebook_config.py
#   - an operation or a check of the notebook's own: a script of its own in
#     .scripts/ that imports this one, never a copy of it
#   - a rule for one type: that type's declaration in Types/
#   - a fix every notebook needs: ask the template for it, with an issue -
#     .claude/notebook/requests.md
# The whole table: .claude/notebook/upstream.md, "The outlets".
"""Set up this checkout of a notebook: what git keeps per clone rather than in
the repository. Run it once in a fresh clone; running it again is harmless.

  checkout.py [<template URL>]      the URL only when the config has no TEMPLATE
  checkout.py --quiet               say something only when something was done, and never fail

  - the template, fetched as refs/template/head, which the guard compares against
  - the guard: `upstream.py verify --staged` as the pre-commit hook

Setup runs this for a new notebook, and `notebook.py open` and `close` run it
quietly, since a session commits after them (.claude/notebook/upstream.md,
"The guard").
"""
import os, sys

# `python3 -I` isolates sys.path, which drops this script's own directory -
# so the module beside it is not importable without putting it back.
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import upstream

quiet = "--quiet" in sys.argv
url = next((a for a in sys.argv[1:] if not a.startswith("--")), None)
done = []
try:
    if upstream.git("rev-parse", "--verify", "--quiet", upstream.REF, check=False).returncode:
        upstream.fetch(url, quiet=quiet)
        done.append("fetched the template")
    if not upstream.guarded():
        upstream.install_hook()
        done.append("installed the guard")
    elif upstream.hook_path().read_text(errors="replace") != upstream.HOOK:
        # An older guard: the hook's own text changed upstream, and git keeps
        # hooks per clone, so nothing else would ever bring it level.
        upstream.install_hook()
        done.append("brought the guard up to date")
except SystemExit as e:
    if not quiet:
        raise
    print(f"this checkout has no guard yet: {e} - run `checkout.py` (upstream.md, \"The guard\")")
    sys.exit(0)
if done or not quiet:
    print("this checkout is set up" + ("" if done else " - nothing to do"))
